<script setup>
import {ref,onMounted,watch,computed,nextTick} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api,formatTime} from '../lib/api'
import {unitTitle} from '../data/curriculum'
import {defineAsyncComponent} from 'vue'
const LearningCharts=defineAsyncComponent(()=>import('../components/LearningCharts.vue'))
import SourceStats from '../components/SourceStats.vue'
import RewardSettings from '../components/RewardSettings.vue'
import SourceBadge from '../components/SourceBadge.vue'
import GameHeader from '../components/GameHeader.vue'
import AdminPointGrants from '../components/AdminPointGrants.vue'
import AdminContentManager from '../components/AdminContentManager.vue'
import AdminMailbox from '../components/AdminMailbox.vue'
import AdminProfile from '../components/AdminProfile.vue'
import AdminGameRecords from '../components/AdminGameRecords.vue'
import AdminOnline from '../components/AdminOnline.vue'
import {useMessages} from '../stores/messages'
const deleteTarget=ref(null),deleteLogin=ref(''),deleting=ref(false);
function askDelete(student){deleteTarget.value=student;deleteLogin.value='';error.value=''}
async function removeStudent(){if(deleting.value||deleteLogin.value!==deleteTarget.value?.login)return;deleting.value=true;try{await api('/admin/students/'+deleteTarget.value.id,{method:'DELETE',body:{confirmLogin:deleteLogin.value}});if(detail.value?.user.id===deleteTarget.value.id)detail.value=null;deleteTarget.value=null;message.value='학생 계정을 삭제했어요. 로그인과 기존 세션이 차단됩니다.';await load()}catch(e){error.value=e.message}finally{deleting.value=false}}
const messages=useMessages();const dashboard=ref(null),error=ref(''),message=ref(''),search=ref(''),classFilter=ref(''),subjectFilter=ref('all'),className=ref(''),detail=ref(null),releaseClass=ref('unassigned'),releaseSubject=ref('vue'),selectedUnits=ref([]),savingRelease=ref(false),creatingClass=ref(false)
async function load(){try{dashboard.value=await api('/admin/dashboard?'+new URLSearchParams({search:search.value,classId:classFilter.value,subject:subjectFilter.value}));error.value='';syncSelection()}catch(e){error.value=e.message}}
async function command(fn,text){error.value='';message.value='';try{await fn();message.value=text;await load()}catch(e){error.value=e.message}}
async function open(student){try{detail.value=await api('/admin/students/'+student.id)}catch(e){error.value=e.message}}
async function assign(id,value){await command(()=>api('/admin/students/'+id+'/class',{method:'PUT',body:{classId:value}}),'기수를 변경했어요.')}
function releaseUnits(){return dashboard.value?.subjects.find(s=>s.id===releaseSubject.value)?.units??[]}
function titleFor(i){return releaseUnits().find(u=>u.number===i)?.title??unitTitle(releaseSubject.value,i)}
function syncSelection(){const current=dashboard.value?.releases.find(r=>r.class_id===releaseClass.value&&r.subject===releaseSubject.value);selectedUnits.value=[...(current?.units??Array.from({length:current?.max_unit??0},(_,i)=>i+1))]}
watch([releaseClass,releaseSubject],syncSelection)
async function saveRelease(){if(savingRelease.value)return;savingRelease.value=true;await command(()=>api('/admin/releases',{method:'PUT',body:{classId:releaseClass.value,subject:releaseSubject.value,units:[...selectedUnits.value]}}),'선택한 학습 항목을 공개했어요. 해제한 항목의 기록은 보존됩니다.');savingRelease.value=false}
async function registerCohort(){if(creatingClass.value||!className.value.trim())return;creatingClass.value=true;error.value='';message.value='';try{const created=await api('/admin/classes',{method:'POST',body:{name:className.value}});await load();releaseClass.value=created.id;className.value='';message.value='기수를 등록했어요. 학생 대시보드에서 학생을 배정해 주세요.'}catch(e){error.value=e.message}finally{creatingClass.value=false}}
async function approve(id){await command(()=>api('/admin/students/'+id+'/migration',{method:'POST'}),'기존 코인과 기록을 이전했어요.');if(detail.value?.user.id===id)await open(detail.value.user)}
const route=useRoute(),router=useRouter(),sections=[{id:'students',icon:'▥',name:'학생 현황',description:'학생 검색 · 학습 진도 · 상세 기록'},{id:'content',icon:'▤',name:'과목·공식 문제',description:'과목·단원 등록 · 공식 문제 작성'},{id:'points',icon:'◆',name:'포인트 관리',description:'학생 보너스 지급 · 퀴즈 보상 설정'},{id:'mail',icon:'✉',name:'학생 쪽지함',description:'쪽지 확인 · 보내기 · 답장'},{id:'cohorts',icon:'⚑',name:'기수·진도',description:'기수 등록 · 학습 항목 공개'},{id:'games',icon:'🏆',name:'게임 기록',description:'명예의 전당 조회 · 기록 삭제 · 복원'},{id:'profile',icon:'⚙',name:'내 정보',description:'관리자 표시 이름 변경'}],activeSection=ref(sections.some(s=>s.id===route.query.section)?route.query.section:'students')
const selectedSection=computed(()=>sections.find(s=>s.id===activeSection.value)),averageProgress=computed(()=>Math.round((dashboard.value?.students??[]).reduce((n,s)=>n+s.percent,0)/Math.max(1,dashboard.value?.students.length??0)))
function chooseSection(id){activeSection.value=id;router.replace({path:'/admin',query:{...route.query,section:id}})}
watch(()=>route.query.section,id=>{if(sections.some(s=>s.id===id))activeSection.value=id})
async function showInbox(){chooseSection('mail');await nextTick();document.getElementById('admin-private-inbox')?.scrollIntoView({behavior:'smooth'})}
onMounted(load)
</script>
<template>
<div class="admin-console-page">
<GameHeader tag="TEACHER CONSOLE" title="관리자 페이지" description="원하는 메뉴를 선택해 학생과 학습을 관리하세요."/>
<p v-if="error" class="notice" role="alert">{{error}}</p><p v-if="message" class="notice" role="status">{{message}}</p>
<template v-if="dashboard">
<section class="admin-overview" aria-label="관리자 요약">
<button class="admin-overview-card" @click="chooseSection('students')"><span>▥ 조회 중인 학생</span><strong>{{dashboard.students.length}}<small>명</small></strong><em>학생 현황 보기 →</em></button>
<button class="admin-overview-card" @click="chooseSection('students')"><span>✦ 평균 공개 진도</span><strong>{{averageProgress}}<small>%</small></strong><em>학습 진행률 확인 →</em></button>
<button class="admin-overview-card" @click="showInbox"><span>✉ 답변 대기 쪽지</span><strong>{{messages.pending}}<small>개</small></strong><em>쪽지함 바로가기 →</em></button>
<button class="admin-overview-card" @click="chooseSection('cohorts')"><span>⚑ 등록 기수</span><strong>{{dashboard.classes.filter(c=>c.id!=='unassigned').length}}<small>개</small></strong><em>기수·공개 진도 관리 →</em></button>
</section>
<AdminOnline/>
<nav class="admin-section-nav" aria-label="관리자 메뉴"><button v-for="tab in sections" :key="tab.id" :class="{active:activeSection===tab.id}" :aria-pressed="activeSection===tab.id" @click="chooseSection(tab.id)"><span>{{tab.icon}}</span>{{tab.name}}<b v-if="tab.id==='mail'&&messages.pending" class="unread-badge">{{messages.pending}}</b></button></nav>
<header class="admin-section-heading"><span>{{selectedSection.icon}}</span><div><h2>{{selectedSection.name}}</h2><p>{{selectedSection.description}}</p></div></header>
<div class="admin-section-area" :data-section="activeSection">
<template v-if="activeSection==='students'"><section class="panel study-history"><h2>학생 대시보드</h2><form class="mistake-filters" @submit.prevent="load"><label>학생 검색<input v-model="search" placeholder="이름 또는 아이디"/></label><label>기수<select v-model="classFilter"><option value="">전체 기수</option><option v-for="c in dashboard.classes" :value="c.id" :key="c.id">{{c.name}}</option></select></label><label>과목<select v-model="subjectFilter"><option value="all">전체 과목</option><option v-for="s in dashboard.subjects" :value="s.id" :key="s.id">{{s.name}}</option></select></label><button>검색·필터 적용</button></form><SourceStats :class-id="classFilter" :subject="subjectFilter"/><LearningCharts :rows="dashboard.students" names="nickname" title="학생 대시보드 차트"/><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>학생명</th><th>레벨</th><th>보유 포인트</th><th>기수</th><th>공개 진도 진행률</th><th>학생 제작 풀이</th><th>복습 필요</th><th>누적 공부시간</th><th>최근 학습일</th><th>상세</th><th>계정 관리</th></tr></thead><tbody><tr v-for="s in dashboard.students" :key="s.id"><td>{{s.nickname}}<small>{{s.login}}</small></td><td><b>Lv.{{s.level}}</b></td><td><b>🪙 {{s.coins.toLocaleString()}} P</b></td><td><select :value="s.classId" @change="assign(s.id,$event.target.value)"><option v-for="c in dashboard.classes" :value="c.id" :key="c.id">{{c.name}}</option></select></td><td>{{s.completed}} / {{s.total}} · {{s.percent}}%</td><td>{{s.sourceStats?.stats.student.solved??0}}회 · 정답률 {{s.sourceStats?.stats.student.accuracy??0}}%</td><td>{{s.pending}}문제</td><td>{{formatTime(s.totalSeconds)}}</td><td>{{s.lastStudyDate??'기록 없음'}}</td><td><button @click="open(s)">보기</button></td><td><button class="danger-button" @click="askDelete(s)">계정 삭제</button></td></tr></tbody></table></div><p v-if="!dashboard.students.length">조건에 맞는 학생이 없어요.</p></section><section v-if="detail" class="panel study-history"><button class="text-button" @click="detail=null">상세 닫기</button><h2>{{detail.user.nickname}} · {{detail.user.className}}</h2><div class="toolbar" aria-label="학생 레벨과 보유 포인트"><b>현재 레벨 Lv.{{detail.level}}</b><b>🪙 보유 포인트 {{detail.coins.toLocaleString()}} P</b><button class="light" @click="open(detail.user)">현재 정보 새로고침</button></div><p>오늘 {{formatTime(detail.todaySeconds)}} / 누적 {{formatTime(detail.totalSeconds)}}</p><div class="study-history-row" v-for="s in detail.subjects" :key="s.id"><b>{{s.name}}</b><span>{{s.completed}} / {{s.total}} · {{s.percent}}%</span><span>{{formatTime((detail.subjectTimes.find(t=>t.subject===s.id)?.ms??0)/1000)}}</span></div><LearningCharts :rows="detail.subjects.map(s=>({...s,totalSeconds:(detail.subjectTimes.find(t=>t.subject===s.id)?.ms??0)/1000}))" title="학생 과목별 차트"/><SourceStats :student-id="detail.user.id"/><h3>퀴즈 결과</h3><p v-if="!detail.history.length">아직 퀴즈 기록이 없어요.</p><div v-for="h in detail.history" :key="h.id" class="study-history-row"><span><SourceBadge v-for="source in (h.sources??['official'])" :key="source" :source="source"/> {{h.subject}} · {{h.mode}}</span><span>{{h.done?h.result.score+'점 · '+h.result.correct+'/'+h.result.total:'진행 중'}}</span><small>{{new Date(h.startedAt).toLocaleString('ko-KR')}}</small></div><h3>오답 현황</h3><article v-for="m in detail.mistakes" :key="m.question_id" class="mistake-entry"><SourceBadge :source="m.source" :creator-name="m.creatorName" :creator-id="m.creatorId" :post-id="m.postId"/><h3>{{m.question}}</h3><p>{{m.reviewed?'복습 완료':'복습 필요'}} · 오답 {{m.wrong_count}}회</p><p>최근 답: {{m.last_answer}} / 정답: {{m.correctAnswer}}</p></article><h3>일별 공부시간 (한국 시간)</h3><div v-for="day in detail.studyDays" :key="day.day" class="record"><span>{{day.day}}</span><span>{{formatTime(day.ms/1000)}}</span></div><template v-if="detail.migration"><h3>기존 브라우저 기록 이전</h3><p>상태 {{detail.migration.status}} · 기존 코인 {{detail.migration.snapshot.coins}}</p><details><summary>기존 학습·게임 기록 원본 확인</summary><pre class="migration-json">{{JSON.stringify(detail.migration.snapshot,null,2)}}</pre></details><button v-if="detail.migration.status==='pending'" @click="approve(detail.user.id)">검토한 기존 코인·기록 승인</button></template></section></template>
<AdminGameRecords v-else-if="activeSection==='games'"/>
<AdminProfile v-else-if="activeSection==='profile'"/>
<AdminContentManager v-else-if="activeSection==='content'" @updated="load"/>
<template v-else-if="activeSection==='points'"><AdminPointGrants/><RewardSettings/></template>
<AdminMailbox v-else-if="activeSection==='mail'" id="admin-private-inbox" :classes="dashboard.classes"/>
<template v-else-if="activeSection==='cohorts'"><section class="panel study-history"><h2>기수 관리와 진도 공개</h2><form class="toolbar" @submit.prevent="registerCohort"><label>새 기수 이름 <input v-model="className" required maxlength="40"/></label><button :disabled="creatingClass||!className.trim()">{{creatingClass?'등록 중…':'기수 등록'}}</button></form><form class="release-form" @submit.prevent="saveRelease"><div class="mistake-filters"><label>기수<select v-model="releaseClass"><option v-for="c in dashboard.classes" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>과목<select v-model="releaseSubject"><option v-for="s in dashboard.subjects" :key="s.id" :value="s.id">{{s.name}}</option></select></label></div><fieldset class="release-options" :disabled="savingRelease"><legend>공개할 학습 항목 선택</legend><p>체크한 항목만 공개됩니다. 순서와 관계없이 여러 개를 선택할 수 있어요.</p><div class="toolbar"><button type="button" class="light" @click="selectedUnits=releaseUnits().map(u=>u.number)">전체 선택</button><button type="button" class="light" @click="selectedUnits=[]">전체 해제</button></div><label v-for="u in releaseUnits()" :key="u.number" :class="['release-check',{checked:selectedUnits.includes(u.number)}]"><input v-model="selectedUnits" type="checkbox" :value="u.number"/><span>{{u.title}}</span><small>{{selectedUnits.includes(u.number)?'공개 예정':'잠금 예정'}}</small></label></fieldset><button :disabled="savingRelease">{{savingRelease?'저장 중…':'선택 항목 공개 저장'}}</button></form><p>현재 저장된 공개 항목: {{dashboard.releases.find(r=>r.class_id===releaseClass&&r.subject===releaseSubject)?.units?.map(i=>titleFor(i)).join(' / ')||'전체 잠금'}}</p></section><section class="panel study-history"><h2>기존 기록 이전 신청</h2><div v-for="m in dashboard.migrations" :key="m.user_id" class="study-history-row"><b>{{m.name}} ({{m.login}})</b><span>{{m.claimedCoins}}코인 · {{m.status}}</span><button @click="open({id:m.user_id})">원본 검토</button></div></section></template>
</div>
</template>
</div>
<div v-if="deleteTarget" class="delete-account-overlay" @keydown.esc="!deleting&&(deleteTarget=null)"><section class="panel delete-account-dialog" role="dialog" aria-modal="true" aria-label="학생 계정 삭제 확인"><h2>학생 계정을 삭제할까요?</h2><p><b>{{deleteTarget.nickname}}</b> · {{deleteTarget.login}} · {{deleteTarget.className}}</p><p>삭제 즉시 로그인과 기존 세션이 차단되고 학생 목록·친구 검색에서 제외됩니다. 기존 학습·포인트 기록은 보존됩니다.</p><form @submit.prevent="removeStudent"><label for="delete-login">확인을 위해 학생 아이디를 입력하세요.</label><input id="delete-login" v-model="deleteLogin" autocomplete="off" :placeholder="deleteTarget.login" :disabled="deleting"/><p v-if="error" role="alert">{{error}}</p><div class="toolbar"><button type="button" class="light" :disabled="deleting" @click="deleteTarget=null">취소</button><button class="danger-button" :disabled="deleting||deleteLogin!==deleteTarget.login">{{deleting?'삭제 중…':'학생 계정 삭제'}}</button></div></form></section></div></template>
